89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /**
108	     * Normalize the optional email: absent stays absent; when present it must be syntactically
109	     * valid and is lower-cased. Returns {@code false} if present but invalid.
110	     */
111	    private boolean normalizeEmail(Owner owner) {
112	        String email = owner.getEmail();
113	        if (email == null || email.isEmpty()) {
114	            owner.setEmail(null);
115	            return true;
116	        }
117	        if (!EMAIL_PATTERN.matcher(email).matches()) {
118	            return false;
119	        }
120	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
121	        return true;
122	    }
123	
124	    /**
125	     * Return {@code true} when the given (already lower-cased) email is non-null and already used by
126	     * any existing owner, comparing case-insensitively on the lower-cased email.
127	     */
128	    private boolean isEmailAlreadyUsed(String email) {
129	        if (email == null) {
130	            return false;
131	        }
132	        for (Owner existing : this.clinicService.findAllOwners()) {
133	            String existingEmail = existing.getEmail();
134	            if (existingEmail != null && email.equals(existingEmail.toLowerCase(java.util.Locale.ROOT))) {
135	                return true;
136	            }
137	        }
138	        return false;
139	    }
140	
141	    /**
142	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
143	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
144	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
145	     *
146	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
147	     *         a valid E.164 number.
148	     */
149	    private static String toE164(String raw) {
150	        if (raw == null) {
151	            return null;
152	        }
153	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
154	        String digits;
155	        if (cleaned.startsWith("+")) {
156	            digits = cleaned.substring(1);
157	        } else {
158	            if (cleaned.startsWith("0")) {
159	                cleaned = cleaned.substring(1);
160	            }
161	            digits = "61" + cleaned;
162	        }
163	        if (!digits.matches("\\d{8,15}")) {
164	            return null;
165	        }
166	        return "+" + digits;
167	    }
168	
169	    /**
170	     * Build the customer code {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three
171	     * letters of the city, LAST3 the upper-cased first three letters of the last name and NNNN a
172	     * per-city 4-digit zero-padded sequence equal to one more than the owners already in that city
173	     * (e.g. {@code SYD-SMI-0007}).
174	     */
175	    private String nextCustomerCode(String city, String lastName) {
176	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
177	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
178	        int sequence = 1;
179	        for (Owner existing : this.clinicService.findAllOwners()) {
180	            if (city.equalsIgnoreCase(existing.getCity())) {
181	                sequence++;
182	            }
183	        }
184	        return String.format("%s-%s-%04d", city3, last3, sequence);
185	    }
186	
187	    /** Common street-type abbreviations expanded during address normalization. */
188	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
189	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
190	
191	    /**
192	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
193	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
194	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
195	     */
196	    private static String normalizeAddress(String value) {
197	        if (value == null) {
198	            return "";
199	        }
200	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
201	        if (collapsed.isEmpty()) {
202	            return "";
203	        }
204	        String[] tokens = collapsed.split(" ");
205	        StringBuilder sb = new StringBuilder(collapsed.length());
206	        for (int i = 0; i < tokens.length; i++) {
207	            if (i > 0) {
208	                sb.append(' ');
209	            }
210	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
211	        }
212	        return sb.toString();
213	    }
214	
215	    /**
216	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
217	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
218	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
219	     */
220	    private static String normalizeForHousehold(String value) {
221	        if (value == null) {
222	            return "";
223	        }
224	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
225	    }
226	
227	    /**
228	     * Return the owners that already share this owner's household, i.e. have the same last name and
229	     * address compared case-insensitively with collapsed whitespace.
230	     */
231	    private List<Owner> householdMembers(Owner owner) {
232	        String lastName = normalizeForHousehold(owner.getLastName());
233	        String address = normalizeForHousehold(owner.getAddress());
234	        List<Owner> members = new java.util.ArrayList<>();
235	        for (Owner existing : this.clinicService.findAllOwners()) {
236	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
237	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
238	                members.add(existing);
239	            }
240	        }
241	        return members;
242	    }
243	
244	    /**
245	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
246	     * last name and address compared case-insensitively with collapsed whitespace.
247	     */
248	    private boolean sharesHouseholdWithExisting(Owner owner) {
249	        return !householdMembers(owner).isEmpty();
250	    }
251	
252	    /**
253	     * Count the existing owners that share this owner's first name and last name, compared
254	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
255	     */
256	    private int namesakeCount(Owner owner) {
257	        String firstName = owner.getFirstName();
258	        String lastName = owner.getLastName();
259	        int count = 0;
260	        for (Owner existing : this.clinicService.findAllOwners()) {
261	            if (firstName != null && lastName != null
262	                && firstName.equalsIgnoreCase(existing.getFirstName())
263	                && lastName.equalsIgnoreCase(existing.getLastName())) {
264	                count++;
265	            }
266	        }
267	        return count;
268	    }
269	
270	    /**
271	     * A stable, shared household identifier derived from the normalized last name and address, so every
272	     * owner in the same household deterministically resolves to the same value.
273	     */
274	    private static String householdIdFor(Owner owner) {
275	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
276	        try {
277	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
278	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
279	            StringBuilder sb = new StringBuilder(24);
280	            for (int i = 0; i < 12; i++) {
281	                sb.append(String.format("%02X", digest[i]));
282	            }
283	            return sb.toString();
284	        }
285	        catch (java.security.NoSuchAlgorithmException e) {
286	            throw new IllegalStateException(e);
287	        }
288	    }
289	
290	    /** Maximum number of owners permitted in a single city. */
291	    private static final int CITY_CAPACITY = 50;
292	
293	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
294	    private static final int DAILY_CREATE_LIMIT = 100;
295	
296	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
297	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
298	
299	    /**
300	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
301	     * Used to enforce the per-city capacity on create (before this owner is saved).
302	     */
303	    private int cityOwnerCount(Owner owner) {
304	        String city = owner.getCity();
305	        int count = 0;
306	        for (Owner existing : this.clinicService.findAllOwners()) {
307	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
308	                count++;
309	            }
310	        }
311	        return count;
312	    }
313	
314	    /**
315	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
316	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
317	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
318	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
319	     */
320	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
321	        switch (date.getDayOfWeek()) {
322	            case SATURDAY:
323	                return date.plusDays(2);
324	            case SUNDAY:
325	                return date.plusDays(1);
326	            default:
327	                return date;
328	        }
329	    }
330	
331	    /**
332	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
333	     * per-day create limit on create (before this owner is saved).
334	     */
335	    private int ownersRegisteredOn(java.time.LocalDate day) {
336	        int count = 0;
337	        for (Owner existing : this.clinicService.findAllOwners()) {
338	            if (day.equals(existing.getRegistrationDate())) {
339	                count++;
340	            }
341	        }
342	        return count;
343	    }
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Override
347	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
348	        HttpHeaders headers = new HttpHeaders();
349	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
350	        String telephone = toE164(owner.getTelephone());
351	        if (telephone == null) {
352	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
353	        }
354	        if (!normalizeEmail(owner)) {
355	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
356	        }
357	        String address = normalizeAddress(owner.getAddress());
358	        if (address.isEmpty()) {
359	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
360	        }
361	        owner.setAddress(address);
362	        java.time.LocalDate registrationDate = toBusinessDay(
363	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
364	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
365	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
366	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
367	        }
368	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
369	            return new ResponseEntity<>(HttpStatus.CONFLICT);
370	        }
371	        for (Owner existing : this.clinicService.findAllOwners()) {
372	            String existingTelephone = toE164(existing.getTelephone());
373	            if (telephone.equals(existingTelephone)) {
374	                return new ResponseEntity<>(HttpStatus.CONFLICT);
375	            }
376	        }
377	        if (isEmailAlreadyUsed(owner.getEmail())) {
378	            return new ResponseEntity<>(HttpStatus.CONFLICT);
379	        }
380	        List<Owner> householdMembers = householdMembers(owner);
381	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
382	        if (!sharesHousehold && !householdMembers.isEmpty()) {
383	            return new ResponseEntity<>(HttpStatus.CONFLICT);
384	        }
385	        if (sharesHousehold && !householdMembers.isEmpty()) {
386	            String householdId = householdMembers.stream()
387	                .map(Owner::getHouseholdId)
388	                .filter(id -> id != null && !id.isBlank())
389	                .findFirst()
390	                .orElseGet(() -> householdIdFor(owner));
391	            owner.setHouseholdId(householdId);
392	            for (Owner member : householdMembers) {
393	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
394	                    member.setHouseholdId(householdId);
395	                    this.clinicService.saveOwner(member);
396	                }
397	            }
398	        }
399	        owner.setNamesakeCount(namesakeCount(owner));
400	        owner.setHouseholdSize(householdMembers.size() + 1);
401	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
402	        owner.setTelephone(telephone);
403	        owner.setRegistrationDate(registrationDate);
404	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
405	        this.clinicService.saveOwner(owner);
406	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
407	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
408	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
409	        headers.setLocation(UriComponentsBuilder.newInstance()
410	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
411	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
412	    }
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Override
416	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
417	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
418	        if (currentOwner == null) {
419	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
420	        }
421	        currentOwner.setAddress(ownerFieldsDto.getAddress());
422	        currentOwner.setCity(ownerFieldsDto.getCity());
423	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
424	        currentOwner.setLastName(ownerFieldsDto.getLastName());
425	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
426	        currentOwner.setEmail(ownerFieldsDto.getEmail());
427	        if (!normalizeEmail(currentOwner)) {
428	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
429	        }
430	        this.clinicService.saveOwner(currentOwner);
431	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
432	    }
433	
434	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
435	    @Transactional
436	    @Override
437	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
438	        Owner owner = this.clinicService.findOwnerById(ownerId);
439	        if (owner == null) {
440	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
441	        }
442	        this.clinicService.deleteOwner(owner);
443	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
444	    }
445	
446	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
447	    @Override
448	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
449	        Owner owner = this.clinicService.findOwnerById(ownerId);
450	        if (owner == null) {
451	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
452	        }
453	        HttpHeaders headers = new HttpHeaders();
454	        Pet pet = petMapper.toPet(petFieldsDto);
455	        owner.setId(ownerId);
456	        pet.setOwner(owner);
457	        pet.getType().setName(null);
458	        this.clinicService.savePet(pet);
459	        PetDto petDto = petMapper.toPetDto(pet);
460	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
461	            .buildAndExpand(pet.getId()).toUri());
462	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
463	    }
464	
465	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
466	    @Override
467	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
468	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
469	        if (currentOwner != null) {
470	            Pet currentPet = this.clinicService.findPetById(petId);
471	            if (currentPet != null) {
472	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
473	                currentPet.setName(petFieldsDto.getName());
474	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
475	                this.clinicService.savePet(currentPet);
476	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
477	            }
478	        }
479	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
480	    }
