489	        visit.setPet(pet);
490	        this.clinicService.saveVisit(visit);
491	        VisitDto visitDto = visitMapper.toVisitDto(visit);
492	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
493	            .buildAndExpand(visit.getId()).toUri());
494	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
495	    }
496	
497	
498	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
499	    @Override
500	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
501	        Owner owner = this.clinicService.findOwnerById(ownerId);
502	        if (owner != null) {
503	            Pet pet = owner.getPet(petId);
504	            if (pet != null) {
